"""HTML templates and static files, embedded so the project has no folders."""
TEMPLATES = {'base.html': '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>{% block title %}Coldstack{% endblock %} · Coldstack</title><link rel="stylesheet" href="/static/style.css"></head>\n<body>\n<aside>\n  <div class="logo">cold<span>stack</span></div>\n  {% set p = request.url.path %}\n  <nav>\n    <a href="/" class="{{ \'on\' if p == \'/\' }}">Dashboard</a>\n    <a href="/leads/search" class="{{ \'on\' if p.startswith(\'/leads/search\') }}">Find leads</a>\n    <a href="/leads" class="{{ \'on\' if p == \'/leads\' or p.startswith(\'/lists\') }}">Lead lists</a>\n    <a href="/campaigns" class="{{ \'on\' if p.startswith(\'/campaigns\') }}">Campaigns</a>\n    <a href="/unibox" class="{{ \'on\' if p.startswith(\'/unibox\') }}">Master inbox {% if unread %}<span class="pill">{{ unread }}</span>{% endif %}</a>\n    <a href="/inboxes" class="{{ \'on\' if p.startswith(\'/inboxes\') }}">Inboxes &amp; warmup</a>\n    <a href="/settings" class="{{ \'on\' if p.startswith(\'/settings\') }}">Settings</a>\n    <a href="/docs" target="_blank">API docs ↗</a>\n  </nav>\n  <div class="foot">Leads: {{ provider }}<br>AI: {{ \'Claude connected\' if ai_on else \'offline templates\' }}</div>\n</aside>\n<main>\n  {% if request.query_params.get(\'ok\') %}<div class="flash ok">{{ request.query_params.get(\'ok\') }}</div>{% endif %}\n  {% if request.query_params.get(\'err\') %}<div class="flash err">{{ request.query_params.get(\'err\') }}</div>{% endif %}\n  {% block content %}{% endblock %}\n</main>\n<script src="/static/app.js"></script>\n{% block scripts %}{% endblock %}\n</body></html>\n', 'campaign.html': '{% extends "base.html" %}{% block title %}{{ c.name }}{% endblock %}\n{% block content %}\n<div class="row"><div><h1>{{ c.name }} <span class="badge b-{{ c.status }}">{{ c.status }}</span></h1>\n<p class="sub">{{ stats.enrolled or 0 }} enrolled · {{ stats.sent or 0 }} sent · {{ stats.replies or 0 }} replies ({{ stats.reply_rate or 0 }}%) · {{ stats.interested or 0 }} positive · {{ stats.bounced or 0 }} bounced</p></div>\n<span class="auto">\n{% if c.status in (\'draft\', \'completed\') or (c.status == \'active\') %}<form method="post" action="/campaigns/{{ c.id }}/launch" style="display:inline" data-confirm="Enrol {{ eligible }} verified leads and start sending inside the window?"><button class="btn primary">{{ \'Add new leads\' if c.status == \'active\' else \'Launch\' }}</button></form>{% endif %}\n{% if c.status in (\'active\',\'paused\') %}<form method="post" action="/campaigns/{{ c.id }}/pause" style="display:inline"><button class="btn">{{ \'Pause\' if c.status == \'active\' else \'Resume\' }}</button></form>{% endif %}\n<form method="post" action="/campaigns/{{ c.id }}/delete" style="display:inline" data-confirm="Delete campaign and its history?"><button class="btn danger">Delete</button></form></span></div>\n\n{% if counts %}<p>{% for k, v in counts.items() %}<span class="badge b-{{ k }}">{{ k }} {{ v }}</span> {% endfor %}</p>{% endif %}\n\n<div class="grid" style="grid-template-columns:1.4fr 1fr">\n<div>\n  <div class="card"><div class="row"><h2 style="margin:0">Sequence</h2><span class="auto"><button class="btn sm" onclick="toggleAI()">✨ Write with AI</button> <button class="btn primary sm" onclick="saveSeq()">Save sequence</button></span></div>\n  <div id="aiBox" class="hide card" style="margin-top:12px;background:#f7f8ff">\n    <label>What are you offering?</label><textarea id="ai_offer" placeholder="We cut batch release time by 40% with a validated cloud QMS for generics manufacturers…"></textarea>\n    <label>Who is it for?</label><input id="ai_audience" placeholder="Heads of Quality at mid-size generics manufacturers">\n    <div class="grid g2"><div><label>Tone</label><select id="ai_tone"><option>friendly, direct</option><option>formal, consultative</option><option>casual, witty</option><option>concise, executive</option></select></div>\n    <div><label>CTA</label><select id="ai_cta"><option value="interest">Interest-based ("worth a chat?")</option><option value="meeting">Meeting ask</option><option value="resource">Offer a resource</option><option value="referral">Ask for the right person</option></select></div></div>\n    <p><button class="btn primary sm" id="aiGo" onclick="aiWrite()">Generate 3-step sequence</button> <span class="small muted">{{ \'Uses Claude.\' if ai_on else \'No Claude key set: uses built-in templates.\' }} Replaces the current draft.</span></p>\n  </div>\n  <p class="small muted">Merge tags: <span class="mono">{{ \'{{first_name}} {{last_name}} {{company}} {{title}} {{industry}} {{location}} {{sender_first_name}}\' }}</span>, fallbacks like <span class="mono">{{ \'{{first_name|there}}\' }}</span>, any CSV column, and spintax <span class="mono">{Hi|Hey}</span>. Leave a follow-up subject empty to send it as a reply in the same thread.</p>\n  <div id="seq"></div>\n  <button class="btn sm" onclick="addStep()">+ Add step</button> <span id="saveMsg" class="small muted"></span>\n  </div>\n\n  <div class="card"><h2>Preview {% if sample %}<span class="small muted">for {{ sample.first_name }} {{ sample.last_name }}, {{ sample.company }}</span>{% endif %}</h2>\n  {% for p in previews %}<h3>Step {{ p.step }} · variant {{ p.label }}</h3><div class="preview"><b>Subject:</b> {{ p.subject }}\n\n{{ p.body }}</div><br>{% else %}<p class="muted small">Save a sequence and attach a list with verified leads to preview.</p>{% endfor %}</div>\n</div>\n\n<div>\n<form class="card" method="post" action="/campaigns/{{ c.id }}/autopilot" style="border-color:#c9d3ff">\n<div class="row"><h2 style="margin:0">Autopilot</h2>\n<label class="check auto"><input type="checkbox" name="autopilot" {{ \'checked\' if c.autopilot }}> On</label></div>\n<p class="small muted">Every day: pulls fresh leads from {{ provider }} with the saved search below (never the same person twice), verifies them, and enrols the good ones. Sequence, follow-ups and reply handling then run by themselves.</p>\n<div class="grid g2"><div><label>New leads per day</label><input type="number" name="autopilot_daily" value="{{ c.autopilot_daily }}"></div>\n<div><label>Stop at (total leads)</label><input type="number" name="autopilot_max_total" value="{{ c.autopilot_max_total }}"></div></div>\n<p class="small muted">≈ {{ c.autopilot_daily }} Apollo credits/day. Make sure your inboxes can send it: each lead gets {{ steps|length }} emails, so you need capacity for about {{ c.autopilot_daily * steps|length }} emails/day once follow-ups kick in.</p>\n<label>Saved search <span class="muted">(set it from <a href="/leads/search?campaign={{ c.id }}">Find leads</a>, or edit)</span></label>\n<textarea name="autopilot_filters" class="mono" style="min-height:110px">{{ c.autopilot_filters }}</textarea>\n<label>Replies</label><select name="reply_mode">\n<option value="draft" {{ \'selected\' if c.reply_mode == \'draft\' }}>AI drafts a reply, I approve it in the master inbox</option>\n<option value="auto" {{ \'selected\' if c.reply_mode == \'auto\' }}>AI replies to interested leads automatically</option>\n<option value="off" {{ \'selected\' if c.reply_mode == \'off\' }}>No AI replies</option></select>\n<label>What the AI should know when replying</label>\n<textarea name="reply_context" style="min-height:120px" placeholder="What you offer, the next step you want (e.g. your booking link), things it must not promise.">{{ c.reply_context }}</textarea>\n{% if c.autopilot_note %}<p class="small"><b>Last run:</b> {{ c.autopilot_note }}</p>{% endif %}\n<button class="btn primary">Save autopilot</button>\n<button class="btn" formaction="/campaigns/{{ c.id }}/autopilot/run">Run now</button></form>\n\n<form class="card" method="post" action="/campaigns/{{ c.id }}/settings"><h2>Settings</h2>\n<label>Name</label><input name="name" value="{{ c.name }}">\n<label>Lead list</label><select name="list_id"><option value="">—</option>{% for l in lists %}<option value="{{ l.id }}" {{ \'selected\' if l.id == c.list_id }}>{{ l.name }}</option>{% endfor %}</select>\n<p class="small muted">{{ eligible }} verified leads eligible.</p>\n<label>Sending inboxes (rotated)</label>\n{% for i in inboxes %}<label class="check"><input type="checkbox" name="inbox_{{ i.id }}" {{ \'checked\' if i.id in attached }}> {{ i.email }} <span class="badge b-{{ i.status }}">{{ i.status }}</span></label>{% else %}<p class="small muted">No inboxes. <a href="/inboxes">Connect one</a>.</p>{% endfor %}\n<label>Timezone</label><select name="timezone">{% for tz in timezones %}<option {{ \'selected\' if tz == c.timezone }}>{{ tz }}</option>{% endfor %}</select>\n<div class="grid g2"><div><label>Window start</label><input type="time" name="window_start" value="{{ c.window_start }}"></div><div><label>Window end</label><input type="time" name="window_end" value="{{ c.window_end }}"></div></div>\n<label>Send days</label><div class="row">{% for d in [\'mon\',\'tue\',\'wed\',\'thu\',\'fri\',\'sat\',\'sun\'] %}<label class="check auto"><input type="checkbox" name="day_{{ d }}" {{ \'checked\' if d in c.send_days }}>{{ d }}</label>{% endfor %}</div>\n<label>Max emails per day (campaign)</label><input type="number" name="daily_cap" value="{{ c.daily_cap }}">\n<label class="check"><input type="checkbox" name="stop_on_reply" {{ \'checked\' if c.stop_on_reply }}> Stop sequence when lead replies</label>\n<label class="check"><input type="checkbox" name="include_risky" {{ \'checked\' if c.include_risky }}> Include risky (catch-all/unverified) leads</label>\n<label class="check"><input type="checkbox" name="unsubscribe_footer" {{ \'checked\' if c.unsubscribe_footer }}> Add opt-out footer (recommended; legally required in many countries)</label>\n<label class="check"><input type="checkbox" name="plain_text" {{ \'checked\' if c.plain_text }}> Plain-text only (best deliverability)</label>\n<button class="btn primary">Save settings</button></form>\n</div></div>\n{% endblock %}\n{% block scripts %}<script>\nlet steps = {{ steps|tojson }};\nconst seqEl = document.getElementById(\'seq\');\nfunction render() {\n  seqEl.innerHTML = steps.map((s, si) => `<div class="step"><div class="head"><b>Step ${si + 1}</b>\n    <span>${si === 0 ? \'<span class="small muted">sent on launch</span>\' : `wait <input type=number min=0 style="width:60px" value="${s.delay_days}" onchange="steps[${si}].delay_days=+this.value"> days after previous`}\n    ${si > 0 ? `<button class="btn sm danger" onclick="steps.splice(${si},1);render()">×</button>` : \'\'}</span></div>\n    ${(s.variants || []).filter(v => v.active !== 0).map((v, vi) => `<div class="variant"><div class="row"><b class="auto">Variant ${esc(v.label)}</b>\n      ${v.sent !== undefined ? `<span class="small muted">${v.sent} sent · ${v.replies} replies${v.sent ? \' (\' + (100 * v.replies / v.sent).toFixed(1) + \'%)\' : \'\'}</span>` : \'<span></span>\'}\n      ${s.variants.length > 1 ? `<button class="btn sm auto" onclick="steps[${si}].variants.splice(${vi},1);render()">remove</button>` : \'\'}</div>\n      <label>Subject${si > 0 ? \' (blank = reply in thread)\' : \'\'}</label><input value="${esc(v.subject)}" oninput="steps[${si}].variants[${vi}].subject=this.value">\n      <label>Body</label><textarea style="min-height:140px" oninput="steps[${si}].variants[${vi}].body=this.value">${esc(v.body)}</textarea></div>`).join(\'\')}\n    <button class="btn sm" onclick="addVariant(${si})">+ A/B variant</button></div>`).join(\'\');\n}\nfunction addStep() { steps.push({delay_days: 3, variants: [{label: \'A\', subject: \'\', body: \'\'}]}); render(); }\nfunction addVariant(si) { const vs = steps[si].variants; vs.push({label: String.fromCharCode(65 + vs.length), subject: vs[0]?.subject || \'\', body: \'\'}); render(); }\nasync function saveSeq() {\n  const m = document.getElementById(\'saveMsg\'); m.textContent = \'Saving…\';\n  try { await postJSON(\'/campaigns/{{ c.id }}/sequence\', {steps}); location.href = \'/campaigns/{{ c.id }}?ok=Sequence%20saved\'; }\n  catch (e) { m.textContent = e.message; }\n}\nfunction toggleAI() { document.getElementById(\'aiBox\').classList.toggle(\'hide\'); }\nasync function aiWrite() {\n  const b = document.getElementById(\'aiGo\'); b.textContent = \'Writing…\';\n  try {\n    const r = await postJSON(\'/campaigns/{{ c.id }}/ai-write\', {offer: ai_offer.value, audience: ai_audience.value, tone: ai_tone.value, cta: ai_cta.value});\n    const old = steps; steps = r.steps.map((s, i) => ({...s, id: old[i]?.id}));\n    render(); document.getElementById(\'saveMsg\').textContent = \'Draft generated. Review it, then Save sequence.\';\n  } catch (e) { alert(e.message); } finally { b.textContent = \'Generate 3-step sequence\'; }\n}\nrender();\n</script>{% endblock %}\n', 'campaigns.html': '{% extends "base.html" %}{% block title %}Campaigns{% endblock %}\n{% block content %}\n<h1>Campaigns</h1><p class="sub">Multi-step sequences with A/B variants, sending windows, inbox rotation and auto-stop on reply.</p>\n<div class="card"><form method="post" action="/campaigns" class="row">\n<div><label>Campaign name</label><input name="name" required placeholder="UK QA leaders – Q1"></div>\n<div><label>Lead list</label><select name="list_id"><option value="">Choose later</option>{% for l in lists %}<option value="{{ l.id }}">{{ l.name }}</option>{% endfor %}</select></div>\n<div class="auto" style="align-self:flex-end"><button class="btn primary">Create campaign</button></div></form></div>\n<div class="card"><h2>Import a campaign pack</h2>\n<p class="small muted">A campaign pack (.json) sets up the lead list, saved search, autopilot, sequence and reply settings in one go.</p>\n<form method="post" action="/campaigns/import" enctype="multipart/form-data" class="row">\n<div><input type="file" name="file" accept=".json,application/json"></div>\n<div class="auto"><button class="btn primary">Import</button></div></form>\n<details><summary class="small muted">…or paste it</summary><form method="post" action="/campaigns/import">\n<textarea name="pack" class="mono" style="min-height:140px"></textarea><button class="btn">Import pasted pack</button></form></details></div>\n<div class="card"><table><tr><th>Campaign</th><th>Status</th><th>Leads</th><th>Sent</th><th>Replies</th><th>Positive</th><th>Bounced</th></tr>\n{% for c in campaigns %}<tr><td><a href="/campaigns/{{ c.id }}">{{ c.name }}</a><div class="small muted">{{ c.list_name or \'no list\' }}</div></td>\n<td><span class="badge b-{{ c.status }}">{{ c.status }}</span></td><td>{{ c.enrolled }}</td><td>{{ c.sent }}</td>\n<td>{{ c.replies }} <span class="small muted">{{ c.reply_rate }}%</span></td><td>{{ c.interested }}</td><td>{{ c.bounced }}</td></tr>\n{% else %}<tr><td colspan="7" class="muted">No campaigns yet.</td></tr>{% endfor %}</table></div>\n{% endblock %}\n', 'dashboard.html': '{% extends "base.html" %}{% block title %}Dashboard{% endblock %}\n{% block content %}\n<h1>Dashboard</h1><p class="sub">Your outbound at a glance.</p>\n\n{% if not inboxes %}\n<div class="card hero"><h2>Get set up in 3 steps</h2>\n<p>1. <a style="color:#fff;text-decoration:underline" href="/inboxes">Connect a sending inbox</a> (Google Workspace or Microsoft 365 on a secondary domain).\n2. <a style="color:#fff;text-decoration:underline" href="/leads/search">Find leads</a> by describing your ideal customer.\n3. <a style="color:#fff;text-decoration:underline" href="/campaigns">Write a sequence</a> with the AI writer and launch.</p></div>\n{% endif %}\n\n<div class="grid g4">\n  <div class="card stat"><div class="l">Sent today</div><div class="n">{{ stats.sent_today }}</div><div class="muted small">{{ stats.sent_total }} all time</div></div>\n  <div class="card stat"><div class="l">Reply rate</div><div class="n">{{ stats.reply_rate }}%</div><div class="muted small">{{ stats.replies }} of {{ stats.contacted }} contacted</div></div>\n  <div class="card stat"><div class="l">Positive replies</div><div class="n">{{ stats.interested }}</div><div class="muted small">{{ stats.positive_rate }}% of contacted</div></div>\n  <div class="card stat"><div class="l">Bounce rate</div><div class="n" style="color:{{ \'var(--bad)\' if stats.bounce_rate > 3 else \'inherit\' }}">{{ stats.bounce_rate }}%</div><div class="muted small">keep under 2–3%</div></div>\n</div>\n\n<div class="grid g2">\n<div class="card"><h2>Last 14 days</h2>\n  {% if daily %}{% set mx = (daily|map(attribute=\'sent\')|max) or 1 %}\n  <div class="spark">{% for d in daily %}<div title="{{ d.d }}: {{ d.sent }} sent, {{ d.replies }} replies" style="height:{{ (100 * (d.sent or 0) / mx)|round(0) }}%"><i style="height:{{ (100 * (d.replies or 0) / ((d.sent or 1)))|round(0) }}%"></i></div>{% endfor %}</div>\n  <p class="small muted">Blue = sent, green = share that got replies.</p>\n  {% else %}<p class="muted">No sends yet.</p>{% endif %}\n</div>\n<div class="card"><h2>Inbox health</h2>\n  {% for i in inboxes %}\n  <div style="margin-bottom:10px"><div class="row"><span>{{ i.email }} <span class="badge b-{{ i.status }}">{{ i.status }}</span></span><span class="auto small muted">{{ i.sent_today }}/{{ i.today_limit }} today</span></div>\n  <div class="bar"><i style="width:{{ (100 * i.sent_today / (i.today_limit or 1))|round(0) }}%"></i></div>\n  {% if i.last_error %}<div class="small" style="color:var(--bad)">{{ i.last_error }}</div>{% endif %}</div>\n  {% else %}<p class="muted">No inboxes connected.</p>{% endfor %}\n</div>\n</div>\n\n<div class="card"><h2>Campaigns</h2>\n<table><tr><th>Campaign</th><th>Status</th><th>Leads</th><th>Sent</th><th>Replies</th><th>Positive</th><th>Bounced</th></tr>\n{% for c in campaigns %}<tr><td><a href="/campaigns/{{ c.id }}">{{ c.name }}</a><div class="small muted">{{ c.list_name or \'no list\' }}</div></td>\n<td><span class="badge b-{{ c.status }}">{{ c.status }}</span></td><td>{{ c.enrolled }} <span class="muted small">({{ c.active }} active)</span></td>\n<td>{{ c.sent }}</td><td>{{ c.replies }} <span class="muted small">{{ c.reply_rate }}%</span></td><td>{{ c.interested }}</td><td>{{ c.bounced }}</td></tr>\n{% else %}<tr><td colspan="7" class="muted">No campaigns yet.</td></tr>{% endfor %}</table></div>\n\n<div class="card"><h2>Activity</h2>\n<table>{% for e in events %}<tr><td class="small muted" style="width:170px">{{ e.created_at[:16].replace(\'T\',\' \') }}</td><td><span class="badge b-{{ \'error\' if e.level==\'error\' else (\'risky\' if e.level==\'warning\' else \'ok\') }}">{{ e.source }}</span></td><td class="small">{{ e.message[:240] }}</td></tr>\n{% else %}<tr><td class="muted">Nothing yet.</td></tr>{% endfor %}</table>\n<p class="small muted">Engine: {% for k, v in worker.items() %}{{ k }} {{ v.last_run }}{% if v.error %} (error){% endif %}{{ \' · \' if not loop.last }}{% endfor %}</p>\n</div>\n{% endblock %}\n', 'inboxes.html': '{% extends "base.html" %}{% block title %}Inboxes{% endblock %}\n{% block content %}\n<h1>Inboxes &amp; warmup</h1>\n<p class="sub">Connect sending mailboxes on secondary domains (e.g. try<i>yourbrand</i>.com), never your main domain. New inboxes ramp up from 5/day to their daily limit over the ramp period, and warm up by emailing each other.</p>\n\n<div class="card"><table><tr><th>Inbox</th><th>Today</th><th>Ramp</th><th>Warmup</th><th>Domain DNS</th><th></th></tr>\n{% for i in inboxes %}<tr>\n<td><b>{{ i.email }}</b> <span class="badge b-{{ i.status }}">{{ i.status }}</span><div class="small muted">{{ i.from_name }} · {{ i.smtp_host }}</div>\n{% if i.last_error %}<div class="small" style="color:var(--bad)">{{ i.last_error }}</div>{% endif %}</td>\n<td>{{ i.sent_today }} / {{ i.today_limit }}<div class="bar" style="width:90px"><i style="width:{{ (100 * i.sent_today / (i.today_limit or 1))|round(0) }}%"></i></div></td>\n<td class="small">{{ i.today_limit }}/day now → {{ i.daily_limit }}/day<br><span class="muted">over {{ i.ramp_days }} days</span></td>\n<td class="small">{% if i.warmup_enabled %}<span class="badge b-active">on</span> {{ i.warmup_today }}/{{ i.warmup_daily }}{% else %}<span class="badge">off</span>{% endif %}</td>\n<td class="small"><a href="#" onclick="dnsCheck(\'{{ i.domain }}\', this);return false">Check SPF/DKIM/DMARC</a></td>\n<td style="white-space:nowrap"><form method="post" action="/inboxes/{{ i.id }}/test" style="display:inline"><button class="btn sm">Test</button></form>\n<form method="post" action="/inboxes/{{ i.id }}/toggle" style="display:inline"><button class="btn sm">{{ \'Pause\' if i.status == \'active\' else \'Resume\' }}</button></form>\n<form method="post" action="/inboxes/{{ i.id }}/delete" style="display:inline" data-confirm="Remove {{ i.email }}?"><button class="btn sm danger">×</button></form></td></tr>\n<tr><td colspan="6" style="padding-top:0"><details><summary class="small muted">Edit limits &amp; signature</summary>\n<form method="post" action="/inboxes/{{ i.id }}/update"><div class="grid g4">\n<div><label>Daily limit</label><input type="number" name="daily_limit" value="{{ i.daily_limit }}"></div>\n<div><label>Ramp days</label><input type="number" name="ramp_days" value="{{ i.ramp_days }}"></div>\n<div><label>Min seconds between sends</label><input type="number" name="min_gap_seconds" value="{{ i.min_gap_seconds }}"></div>\n<div><label>Warmup emails/day</label><input type="number" name="warmup_daily" value="{{ i.warmup_daily }}"></div></div>\n<div class="grid g2"><div><label>From name</label><input name="from_name" value="{{ i.from_name }}"></div>\n<div><label>New password (leave blank to keep)</label><input type="password" name="password" autocomplete="new-password"></div></div>\n<label>Signature</label><textarea name="signature" style="min-height:60px">{{ i.signature }}</textarea>\n<label class="check"><input type="checkbox" name="warmup_enabled" {{ \'checked\' if i.warmup_enabled }}> Warmup enabled</label>\n<button class="btn primary sm">Save</button></form></details></td></tr>\n{% else %}<tr><td colspan="6" class="muted">No inboxes yet.</td></tr>{% endfor %}</table>\n<pre id="dnsOut" class="preview hide"></pre></div>\n\n<div class="card"><h2>Connect an inbox</h2>\n<form method="post" action="/inboxes">\n<div class="grid g3">\n<div><label>Email address</label><input name="email" type="email" required placeholder="alex@tryacme.com"></div>\n<div><label>From name</label><input name="from_name" placeholder="Alex Smith"></div>\n<div><label>Provider</label><select name="preset" id="preset" onchange="document.getElementById(\'custom\').classList.toggle(\'hide\', this.value!==\'custom\')">\n<option value="google">Google Workspace / Gmail</option><option value="microsoft">Microsoft 365 / Outlook</option><option value="zoho">Zoho Mail (EU)</option><option value="custom">Other SMTP/IMAP</option></select></div>\n</div>\n<div id="custom" class="hide grid g3">\n<div><label>SMTP host</label><input name="smtp_host"></div><div><label>SMTP port</label><input name="smtp_port" type="number" value="587"></div>\n<div><label>Security</label><select name="smtp_security"><option value="starttls">STARTTLS</option><option value="ssl">SSL/TLS</option><option value="none">None (local testing)</option></select></div>\n<div><label>IMAP host</label><input name="imap_host"></div><div><label>IMAP port</label><input name="imap_port" type="number" value="993"></div></div>\n<div class="grid g3">\n<div><label>App password</label><input name="password" type="password" required autocomplete="new-password"></div>\n<div><label>Daily limit (after ramp)</label><input name="daily_limit" type="number" value="30"></div>\n<div><label>Ramp-up days</label><input name="ramp_days" type="number" value="14"></div></div>\n<label>Signature</label><textarea name="signature" style="min-height:60px" placeholder="Alex Smith&#10;Head of Partnerships, Acme"></textarea>\n<label class="check"><input type="checkbox" name="warmup_enabled" checked> Enable warmup (needs 2+ inboxes)</label>\n<button class="btn primary">Add inbox</button></form>\n<p class="small muted" style="margin-top:12px"><b>Google:</b> turn on 2-step verification, then create an App Password at myaccount.google.com/apppasswords. <b>Microsoft 365:</b> an admin must enable "Authenticated SMTP" for the mailbox; use an app password if MFA is on.\nKeep each inbox at ~30–50 cold emails/day and use 2–3 inboxes per domain.</p></div>\n{% endblock %}\n{% block scripts %}<script>\nasync function dnsCheck(d, el) {\n  el.textContent = \'checking…\';\n  const r = await (await fetch(\'/api/dns/\' + d)).json();\n  const out = document.getElementById(\'dnsOut\'); out.classList.remove(\'hide\');\n  out.textContent = `${d}\\nMX:    ${r.mx.join(\', \') || \'MISSING\'}\\nSPF:   ${r.spf[0] || \'MISSING\'}\\nDKIM:  ${r.dkim_selectors_found.length ? \'found (\' + r.dkim_selectors_found.join(\', \') + \')\' : \'not found on common selectors\'}\\nDMARC: ${r.dmarc[0] || \'MISSING\'}\\n\\n${r.ok ? \'Looks good.\' : \'Fix the missing records at your domain registrar before sending.\'}`;\n  el.textContent = r.ok ? \'DNS OK ✓\' : \'DNS issues ✗\';\n}\n</script>{% endblock %}\n', 'lead_search.html': '{% extends "base.html" %}{% block title %}Find leads{% endblock %}\n{% block content %}\n<h1>Find leads</h1><p class="sub">Describe who you want to reach in plain English. Coldstack turns it into filters, searches your data provider, then verifies every email before it can be used.</p>\n\n<div class="card hero">\n  <textarea id="icp" placeholder="e.g. Heads of Quality and QA Directors at generic pharma and biosimilar companies in the UK, Ireland and Nordics with 200–5000 employees"></textarea>\n  <div class="row" style="margin-top:10px"><span class="small" style="opacity:.8">Provider: <b>{{ provider }}</b> · {{ \'AI parsing by Claude\' if ai_on else \'keyword parsing (add a Claude key in Settings for better results)\' }}</span>\n  <button class="btn auto" id="parse">Build filters →</button></div>\n</div>\n\n<div class="card" id="filtersCard">\n  <h2>Filters</h2>\n  <p class="small muted" id="summary"></p>\n  <div class="grid g2">\n    <div><label>Job titles (comma separated)</label><input id="f_titles"></div>\n    <div><label>Locations</label><input id="f_locations" placeholder="United Kingdom, Ireland"></div>\n    <div><label>Industries</label><input id="f_industries"></div>\n    <div><label>Company keywords</label><input id="f_keywords"></div>\n  </div>\n  <label>Seniority</label><div class="row">{% for s in seniorities %}<label class="check auto"><input type="checkbox" name="sen" value="{{ s }}">{{ s.replace(\'_\',\' \') }}</label>{% endfor %}</div>\n  <label>Company size (employees)</label><div class="row">{% for r in ranges %}<label class="check auto"><input type="checkbox" name="rng" value="{{ r }}">{{ r.replace(\',\', \'–\') if not r.endswith(\',\') else r[:-1] ~ \'+\' }}</label>{% endfor %}</div>\n  <div style="margin-top:12px"><button class="btn primary" id="search">Search</button> <span id="status" class="muted small"></span></div>\n</div>\n\n<div class="card hide" id="resultsCard">\n  <div class="row"><h2 id="totals" style="margin:0"></h2>\n    <span class="auto"><button class="btn sm" id="prev">←</button> <span id="pg"></span> <button class="btn sm" id="next">→</button></span></div>\n  <p class="small muted" id="note"></p>\n  <table id="results"></table>\n  <div class="card" style="margin:14px 0 0;background:#fafbfc">\n    <h3>Save to a list</h3>\n    <div class="row">\n      <div><label>Existing list</label><select id="list_id"><option value="">+ New list</option>{% for l in lists %}<option value="{{ l.id }}">{{ l.name }}</option>{% endfor %}</select></div>\n      <div><label>New list name</label><input id="list_name" placeholder="UK QA leaders – Nov"></div>\n      <div><label>How many</label><select id="mode"><option value="selected">Selected rows</option><option value="25">Top 25</option><option value="100">Top 100</option><option value="250">Top 250</option><option value="500">Top 500</option></select></div>\n      <div class="auto" style="align-self:flex-end"><button class="btn primary" id="save">Reveal &amp; save</button></div>\n    </div>\n    <p class="small muted" id="saveStatus"></p>\n  </div>\n  <div class="card" style="margin:14px 0 0;background:#f7f8ff">\n    <h3>…or let autopilot pull these every day</h3>\n    <div class="row"><div><select id="ap_campaign">{% for c in campaigns %}<option value="{{ c.id }}" {{ \'selected\' if request.query_params.get(\'campaign\') == c.id|string }}>{{ c.name }}</option>{% else %}<option value="">Create a campaign first</option>{% endfor %}</select></div>\n    <div class="auto"><button class="btn" id="apSave">Use as autopilot search</button></div></div>\n    <p class="small muted" id="apStatus"></p>\n  </div>\n</div>\n{% endblock %}\n{% block scripts %}<script>\nlet page = 1, lastRows = [];\nconst $ = id => document.getElementById(id);\nconst split = v => v.split(\',\').map(s => s.trim()).filter(Boolean);\nfunction getFilters() {\n  return {titles: split($(\'f_titles\').value), locations: split($(\'f_locations\').value), industries: split($(\'f_industries\').value),\n    keywords: split($(\'f_keywords\').value), seniorities: [...document.querySelectorAll(\'[name=sen]:checked\')].map(x => x.value),\n    employee_ranges: [...document.querySelectorAll(\'[name=rng]:checked\')].map(x => x.value)};\n}\nfunction setFilters(f) {\n  $(\'f_titles\').value = (f.titles||[]).join(\', \'); $(\'f_locations\').value = (f.locations||[]).join(\', \');\n  $(\'f_industries\').value = (f.industries||[]).join(\', \'); $(\'f_keywords\').value = (f.keywords||[]).join(\', \');\n  document.querySelectorAll(\'[name=sen]\').forEach(x => x.checked = (f.seniorities||[]).includes(x.value));\n  document.querySelectorAll(\'[name=rng]\').forEach(x => x.checked = (f.employee_ranges||[]).includes(x.value));\n  $(\'summary\').textContent = f.summary || \'\';\n}\n$(\'parse\').onclick = async () => {\n  $(\'parse\').textContent = \'Thinking…\';\n  try { setFilters(await postJSON(\'/api/icp\', {description: $(\'icp\').value})); await runSearch(1); }\n  catch (e) { alert(e.message); } finally { $(\'parse\').textContent = \'Build filters →\'; }\n};\nasync function runSearch(p) {\n  page = p; $(\'status\').textContent = \'Searching…\';\n  try {\n    const r = await postJSON(\'/api/search\', {filters: getFilters(), page, per_page: 25});\n    lastRows = r.rows; $(\'resultsCard\').classList.remove(\'hide\');\n    $(\'totals\').textContent = r.total.toLocaleString() + \' people match\'; $(\'note\').textContent = r.note || \'\';\n    $(\'pg\').textContent = \'page \' + page;\n    $(\'results\').innerHTML = \'<tr><th><input type=checkbox id=all></th><th>Name</th><th>Title</th><th>Company</th><th>Location</th><th>Email</th></tr>\' +\n      r.rows.map((x, i) => `<tr><td><input type=checkbox class=pick data-i=${i}></td><td>${esc(x.first_name)} ${esc(x.last_name)}${x.linkedin_url ? ` <a href="${esc(x.linkedin_url)}" target=_blank class=small>in</a>` : \'\'}</td>\n      <td>${esc(x.title)}</td><td>${esc(x.company)}<div class="small muted">${esc(x.company_domain)} ${esc(x.company_size)}</div></td><td class=small>${esc(x.location)}</td>\n      <td class=small>${x.email ? esc(x.email) : \'<span class=muted>revealed on save</span>\'}</td></tr>`).join(\'\');\n    $(\'all\').onchange = e => document.querySelectorAll(\'.pick\').forEach(c => c.checked = e.target.checked);\n    $(\'status\').textContent = \'\';\n  } catch (e) { $(\'status\').textContent = e.message; }\n}\n$(\'search\').onclick = () => runSearch(1);\n$(\'next\').onclick = () => runSearch(page + 1);\n$(\'prev\').onclick = () => page > 1 && runSearch(page - 1);\n$(\'apSave\').onclick = async () => {\n  const id = $(\'ap_campaign\').value; if (!id) return;\n  await postJSON(`/api/campaigns/${id}/autopilot-filters`, {filters: getFilters()});\n  $(\'apStatus\').innerHTML = `Saved. <a href="/campaigns/${id}">Open the campaign</a> to switch autopilot on.`;\n};\n$(\'save\').onclick = async () => {\n  const mode = $(\'mode\').value, body = {filters: getFilters(), list_id: $(\'list_id\').value || null,\n    list_name: $(\'list_name\').value || ($(\'icp\').value || \'New list\').slice(0, 60), summary: $(\'summary\').textContent};\n  if (mode === \'selected\') { body.rows = [...document.querySelectorAll(\'.pick:checked\')].map(c => lastRows[+c.dataset.i]); if (!body.rows.length) return alert(\'Select some rows first\'); }\n  else body.count = +mode;\n  $(\'saveStatus\').textContent = \'Revealing emails and saving…\';\n  try { const r = await postJSON(\'/api/save\', body);\n    $(\'saveStatus\').innerHTML = `Saved ${r.added} leads (${r.with_email} of ${r.requested} had an email). Verification is running → <a href="/lists/${r.list_id}">open list</a>`;\n  } catch (e) { $(\'saveStatus\').textContent = e.message; }\n};\n</script>{% endblock %}\n', 'leads.html': '{% extends "base.html" %}{% block title %}Lead lists{% endblock %}\n{% block content %}\n<div class="row"><div><h1>Lead lists</h1><p class="sub">Every lead is verified (syntax, domain MX, mailbox) before it can be emailed.</p></div>\n<a class="btn primary auto" href="/leads/search">Find leads</a></div>\n<div class="card"><table><tr><th>List</th><th>Leads</th><th>Valid</th><th>Risky</th><th>Invalid</th><th>Verifying</th><th>Created</th></tr>\n{% for l in lists %}<tr><td><a href="/lists/{{ l.id }}">{{ l.name }}</a><div class="small muted">{{ l.description[:90] }}</div></td>\n<td>{{ l.n }}</td><td><span class="badge b-valid">{{ l.valid }}</span></td><td><span class="badge b-risky">{{ l.risky }}</span></td>\n<td><span class="badge b-invalid">{{ l.invalid }}</span></td><td>{{ l.pending }}</td><td class="small muted">{{ l.created_at[:10] }}</td></tr>\n{% else %}<tr><td colspan="7" class="muted">No lists yet. Find leads or import a CSV.</td></tr>{% endfor %}</table></div>\n\n<div class="card"><h2>Import CSV</h2>\n<p class="small muted">Needs an <b>email</b> column. First name, last name, title, company, domain, LinkedIn etc. are detected automatically. Any other column becomes a merge tag, e.g. a column called <span class="mono">icebreaker</span> → <span class="mono">{{ \'{{icebreaker}}\' }}</span>.</p>\n<form method="post" action="/leads/import" enctype="multipart/form-data" class="row">\n<div><label>File</label><input type="file" name="file" accept=".csv" required></div>\n<div><label>New list name</label><input name="list_name"></div>\n<div><label>…or add to</label><select name="list_id"><option value="">New list</option>{% for l in lists %}<option value="{{ l.id }}">{{ l.name }}</option>{% endfor %}</select></div>\n<div class="auto" style="align-self:flex-end"><button class="btn primary">Import</button></div></form></div>\n{% endblock %}\n', 'list.html': '{% extends "base.html" %}{% block title %}{{ lst.name }}{% endblock %}\n{% block content %}\n<div class="row"><div><h1>{{ lst.name }}</h1><p class="sub">{{ lst.description }}</p></div>\n<span class="auto"><a class="btn" href="/lists/{{ lst.id }}/export">Export CSV</a>\n<form method="post" action="/lists/{{ lst.id }}/reverify" style="display:inline"><button class="btn">Re-verify</button></form>\n<form method="post" action="/lists/{{ lst.id }}/delete" style="display:inline" data-confirm="Delete this list and its leads?"><button class="btn danger">Delete</button></form></span></div>\n<p class="tabs"><a class="badge {{ \'b-active\' if not status }}" href="?">All</a>\n{% for s in [\'valid\',\'risky\',\'invalid\',\'pending\'] %}<a class="badge b-{{ s if status == s else \'\' }}" href="?status={{ s }}">{{ s }} {{ counts.get(s, 0) }}</a>{% endfor %}\n{% if counts.get(\'pending\') %}<span class="small muted">Verifying in the background — refresh to update.</span>{% endif %}</p>\n<div class="card"><table><tr><th>Email</th><th>Name</th><th>Title</th><th>Company</th><th>Location</th><th>Verification</th></tr>\n{% for l in leads %}<tr><td class="small">{{ l.email }}</td><td>{{ l.first_name }} {{ l.last_name }}{% if l.linkedin_url %} <a class="small" target="_blank" href="{{ l.linkedin_url }}">in</a>{% endif %}</td>\n<td class="small">{{ l.title }}</td><td class="small">{{ l.company }}</td><td class="small muted">{{ l.location }}</td>\n<td><span class="badge b-{{ l.verify_status }}">{{ l.verify_status }}</span><div class="small muted">{{ l.verify_detail }}</div></td></tr>\n{% else %}<tr><td class="muted">No leads.</td></tr>{% endfor %}</table>\n{% if leads|length == 1000 %}<p class="small muted">Showing the first 1,000. Export for the full list.</p>{% endif %}</div>\n{% endblock %}\n', 'settings.html': '{% extends "base.html" %}{% block title %}Settings{% endblock %}\n{% block content %}\n<h1>Settings</h1><p class="sub">API keys are stored in your local database. Values set as environment variables override these and are shown as locked.</p>\n{% macro field(k, label, help=\'\', secret=False) %}\n<label>{{ label }}{% if k in env_locked %} <span class="badge">set by env</span>{% endif %}</label>\n<input name="{{ k }}" {% if secret %}type="password" value="{{ \'••••••••\' if s[k] else \'\' }}"{% else %}value="{{ s[k] }}"{% endif %} {{ \'disabled\' if k in env_locked }} autocomplete="off">\n{% if help %}<div class="small muted">{{ help|safe }}</div>{% endif %}\n{% endmacro %}\n<form method="post" action="/settings">\n<div class="grid g2">\n<div class="card"><h2>Lead data</h2>\n<label>Provider</label><select name="lead_provider">\n{% for v, t in [(\'demo\',\'Demo data (synthetic, free)\'),(\'apollo\',\'Apollo.io – free search, credits on reveal\'),(\'pdl\',\'People Data Labs – credits per record\')] %}<option value="{{ v }}" {{ \'selected\' if s.lead_provider == v }}>{{ t }}</option>{% endfor %}</select>\n{{ field(\'apollo_api_key\', \'Apollo master API key\', \'Apollo → Settings → Integrations → API → create a <b>master</b> key. Search needs a paid plan with API access.\', True) }}\n{{ field(\'pdl_api_key\', \'People Data Labs API key\', \'dashboard.peopledatalabs.com\', True) }}\n<h2 style="margin-top:18px">Verification</h2>\n{{ field(\'millionverifier_api_key\', \'MillionVerifier API key (optional, recommended)\', \'Adds a real mailbox check. Without it, leads with good MX records but no mailbox check are marked "risky" unless the provider already verified them.\', True) }}\n<label class="check"><input type="checkbox" name="smtp_probe" {{ \'checked\' if s.smtp_probe == \'1\' }}> Direct SMTP mailbox probe (only works on a server with outbound port 25 open)</label>\n</div>\n<div class="card"><h2>AI (Claude)</h2>\n{{ field(\'anthropic_api_key\', \'Anthropic API key\', \'console.anthropic.com. Powers plain-English lead search, the sequence writer and reply classification.\', True) }}\n{{ field(\'anthropic_model\', \'Model\', \'e.g. claude-sonnet-5-5 (balanced) or claude-haiku-5-5 (cheapest)\') }}\n<h2 style="margin-top:18px">Compliance &amp; links</h2>\n{{ field(\'public_base_url\', \'Public URL of this app\', \'Used in unsubscribe links. Must be reachable by recipients once you send for real (e.g. https://outreach.yourdomain.com).\') }}\n{{ field(\'sender_company\', \'Your company name (footer)\') }}\n{{ field(\'sender_postal_address\', \'Postal address (footer)\', \'Required for US recipients (CAN-SPAM). Good practice under UK PECR/GDPR.\') }}\n{{ field(\'webhook_url\', \'Webhook URL\', \'Receives JSON for every reply, bounce and unsubscribe (Zapier, Make, n8n, your CRM).\') }}\n<h2 style="margin-top:18px">Engine</h2>\n<label class="check"><input type="checkbox" name="send_engine_enabled" {{ \'checked\' if s.send_engine_enabled == \'1\' }}> Sending engine on</label>\n<label class="check"><input type="checkbox" name="warmup_engine_enabled" {{ \'checked\' if s.warmup_engine_enabled == \'1\' }}> Warmup engine on</label>\n</div></div>\n<button class="btn primary">Save settings</button>\n<button class="btn" formaction="/settings/test-provider">Test lead provider</button></form>\n<br>\n<div class="card"><h2>Do-not-contact list ({{ suppression|length }})</h2>\n<p class="small muted">Bounces and unsubscribes are added automatically. Add an address, or a whole domain as <span class="mono">@competitor.com</span>.</p>\n<form method="post" action="/suppression" class="row"><div><textarea name="entries" style="min-height:50px" placeholder="one per line"></textarea></div><div class="auto"><button class="btn">Add</button></div></form>\n<table>{% for x in suppression %}<tr><td class="small">{{ x.email }}</td><td class="small muted">{{ x.reason }}</td><td class="small muted">{{ x.created_at[:10] }}</td>\n<td><form method="post" action="/suppression/delete"><input type="hidden" name="email" value="{{ x.email }}"><button class="btn sm">remove</button></form></td></tr>{% endfor %}</table></div>\n{% endblock %}\n', 'unibox.html': '{% extends "base.html" %}{% block title %}Master inbox{% endblock %}\n{% block content %}\n<h1>Master inbox</h1><p class="sub">{% if pending %}<b>{{ pending }} AI draft{{ \'s\' if pending != 1 }} waiting for your approval.</b> {% endif %}Replies from every connected inbox in one place, auto-labelled. Out-of-office replies don\'t stop the sequence; unsubscribes are suppressed automatically.</p>\n<p class="tabs"><a class="badge {{ \'b-active\' if not label }}" href="/unibox">All</a>\n{% for l in labels %}<a class="badge {{ \'b-\' ~ l if label == l }}" href="/unibox?label={{ l }}">{{ l.replace(\'_\',\' \') }} {{ counts.get(l, 0) }}</a>{% endfor %}</p>\n<div class="split">\n<div class="card list" style="padding:0;max-height:75vh;overflow:auto">\n{% for m in items %}<a class="item {{ \'unread\' if not m.is_read }} {{ \'on\' if current and current.id == m.id }}" href="/unibox?msg={{ m.id }}{{ \'&label=\' ~ label if label }}">\n<div class="row"><span>{{ m.first_name or m.from_addr }} {{ m.last_name or \'\' }}</span><span class="auto badge b-{{ m.classification }}">{{ m.classification.replace(\'_\',\' \') }}</span></div>\n<div class="small muted">{{ m.company or \'\' }} · {{ m.campaign_name or \'\' }} · {{ m.created_at[:16].replace(\'T\',\' \') }}</div>\n<div class="small">{{ m.body[:90] }}</div>{% if m.draft_status == \'ready\' %}<span class="badge b-active">draft ready</span>{% elif m.draft_status == \'sent\' %}<span class="badge">replied</span>{% endif %}</a>\n{% else %}<p class="muted" style="padding:14px">No replies yet. Inboxes are checked every 2 minutes.</p>{% endfor %}\n</div>\n<div>{% if current %}\n<div class="card"><div class="row"><div><h2 style="margin:0">{{ current.first_name }} {{ current.last_name }}</h2>\n<div class="small muted">{{ current.title }} · {{ current.company }} · {{ current.from_addr }}{% if current.linkedin_url %} · <a target="_blank" href="{{ current.linkedin_url }}">LinkedIn</a>{% endif %}</div></div>\n<form class="auto" method="post" action="/unibox/{{ current.id }}/label"><select name="label" onchange="this.form.submit()" style="width:auto">{% for l in labels %}<option {{ \'selected\' if l == current.classification }}>{{ l }}</option>{% endfor %}</select></form></div></div>\n{% for t in thread %}<div class="bubble {{ t.kind }}"><div class="small muted">{{ \'You\' if t.kind == \'out\' else t.from_addr }} · {{ t.created_at[:16].replace(\'T\',\' \') }} · {{ t.subject }}</div>\n{{ t.body }}</div>{% endfor %}\n{% if current.draft_status == \'sent\' %}<p class="small muted">You\'ve replied to this message.</p>{% endif %}\n<form class="card" method="post" action="/unibox/{{ current.id }}/reply"><label>{{ \'AI draft: check it, edit if needed, then send\' if current.draft else \'Reply\' }} <span class="muted">(sent from the same inbox, in the same thread)</span></label>\n<textarea name="body" required style="min-height:150px">{% if current.draft %}{{ current.draft }}{% else %}Hi {{ current.first_name or \'\' }},\n\n{% endif %}</textarea><button class="btn primary">{{ \'Approve & send\' if current.draft else \'Send reply\' }}</button>\n<button class="btn" formaction="/unibox/{{ current.id }}/draft" formnovalidate>{{ \'Rewrite draft\' if current.draft else \'Draft with AI\' }}</button></form>\n{% else %}<div class="card muted">Select a conversation.</div>{% endif %}</div></div>\n{% endblock %}\n', 'unsubscribe.html': '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unsubscribe</title>\n<style>body{font:16px/1.5 -apple-system,Segoe UI,sans-serif;display:flex;justify-content:center;padding:60px 20px;background:#f6f7f9;color:#14161a}\n.box{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:28px;max-width:420px;text-align:center}button{background:#14161a;color:#fff;border:0;border-radius:8px;padding:10px 18px;font:inherit;cursor:pointer}</style></head>\n<body><div class="box">\n{% if not lead %}<p>This link isn\'t valid any more.</p>\n{% elif done %}<h2>You\'re unsubscribed</h2><p>{{ lead.email }} won\'t receive any more emails from us. Sorry for the interruption.</p>\n{% else %}<h2>Unsubscribe?</h2><p>Stop all further emails to <b>{{ lead.email }}</b>.</p><form method="post"><button>Unsubscribe</button></form>{% endif %}\n</div></body></html>\n'}

STATIC = {'app.js': '// Small helpers shared by pages\nasync function postJSON(url, data) {\n  const r = await fetch(url, {method: \'POST\', headers: {\'Content-Type\': \'application/json\'}, body: JSON.stringify(data)});\n  const j = await r.json().catch(() => ({}));\n  if (!r.ok) throw new Error(j.error || j.detail || (\'HTTP \' + r.status));\n  return j;\n}\nfunction esc(s) { return String(s ?? \'\').replace(/[&<>"\']/g, c => ({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c])); }\ndocument.querySelectorAll(\'form[data-confirm]\').forEach(f => f.addEventListener(\'submit\', e => {\n  if (!confirm(f.dataset.confirm)) e.preventDefault();\n}));\n', 'style.css': ':root{--bg:#f6f7f9;--panel:#fff;--ink:#14161a;--muted:#6b7280;--line:#e5e7eb;--brand:#3b5bfd;--brand-ink:#fff;\n--ok:#12805c;--ok-bg:#e7f6ef;--warn:#9a6700;--warn-bg:#fff4d6;--bad:#b42318;--bad-bg:#fdecea;--side:#0f1220;--side-ink:#c9cbe0}\n*{box-sizing:border-box}body{margin:0;font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Roboto,sans-serif;color:var(--ink);background:var(--bg);display:flex;min-height:100vh}\na{color:var(--brand);text-decoration:none}a:hover{text-decoration:underline}\naside{width:220px;background:var(--side);color:var(--side-ink);padding:20px 12px;flex-shrink:0;position:sticky;top:0;height:100vh}\naside .logo{font-weight:700;font-size:18px;color:#fff;padding:4px 10px 18px;letter-spacing:-.3px}aside .logo span{color:#8ea2ff}\naside nav a{display:flex;justify-content:space-between;align-items:center;color:var(--side-ink);padding:8px 10px;border-radius:8px;margin-bottom:2px}\naside nav a:hover,aside nav a.on{background:#1d2238;color:#fff;text-decoration:none}\naside .pill{background:var(--brand);color:#fff;border-radius:10px;padding:0 7px;font-size:12px}\naside .foot{position:absolute;bottom:16px;left:22px;right:12px;font-size:12px;color:#7d81a0}\nmain{flex:1;padding:28px 36px;max-width:1300px}\nh1{font-size:22px;margin:0 0 4px;letter-spacing:-.3px}h2{font-size:16px;margin:0 0 12px}h3{font-size:14px;margin:0 0 8px}\n.sub{color:var(--muted);margin:0 0 22px}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:18px;margin-bottom:18px}\n.grid{display:grid;gap:14px}.g4{grid-template-columns:repeat(4,1fr)}.g3{grid-template-columns:repeat(3,1fr)}.g2{grid-template-columns:1fr 1fr}\n.stat .n{font-size:26px;font-weight:700;letter-spacing:-.5px}.stat .l{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.4px}\ntable{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px 8px;border-bottom:1px solid var(--line);vertical-align:top}\nth{font-size:12px;color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.3px}\ntr:last-child td{border-bottom:0}\n.btn{display:inline-block;border:1px solid var(--line);background:#fff;color:var(--ink);padding:7px 13px;border-radius:8px;cursor:pointer;font:inherit;font-weight:500}\n.btn:hover{border-color:#c7cad1;text-decoration:none}.btn.primary{background:var(--brand);border-color:var(--brand);color:#fff}\n.btn.danger{color:var(--bad)}.btn.sm{padding:4px 9px;font-size:13px}\ninput,select,textarea{font:inherit;border:1px solid var(--line);border-radius:8px;padding:7px 10px;background:#fff;width:100%}\ntextarea{min-height:90px;resize:vertical}label{display:block;font-size:12px;font-weight:600;color:#374151;margin:10px 0 4px}\n.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.row>*{flex:1}.row .auto{flex:0 0 auto}\n.check{display:flex;gap:6px;align-items:center;font-weight:500;font-size:14px;margin:6px 0}.check input{width:auto}\n.badge{display:inline-block;padding:1px 8px;border-radius:10px;font-size:12px;font-weight:600;background:#eef0f4;color:#374151}\n.b-valid,.b-active,.b-interested,.b-ok{background:var(--ok-bg);color:var(--ok)}.b-risky,.b-paused,.b-out_of_office,.b-pending,.b-draft{background:var(--warn-bg);color:var(--warn)}\n.b-invalid,.b-error,.b-bounced,.b-bounce,.b-not_interested,.b-unsubscribe{background:var(--bad-bg);color:var(--bad)}.b-completed,.b-replied{background:#e8edff;color:#2f47c9}\n.flash{padding:10px 14px;border-radius:8px;margin-bottom:16px}.flash.ok{background:var(--ok-bg);color:var(--ok)}.flash.err{background:var(--bad-bg);color:var(--bad)}\n.muted{color:var(--muted)}.small{font-size:12px}.mono{font-family:ui-monospace,Menlo,monospace;font-size:12px}\n.bar{height:6px;background:#eef0f4;border-radius:4px;overflow:hidden}.bar i{display:block;height:100%;background:var(--brand)}\n.chip{display:inline-flex;gap:4px;align-items:center;background:#eef1ff;color:#2f47c9;border-radius:14px;padding:2px 10px;margin:2px;font-size:13px}\n.chip b{cursor:pointer;font-weight:400;opacity:.6}\n.hero{background:linear-gradient(135deg,#1c2350,#3b5bfd);color:#fff;border:0}.hero textarea{border:0;min-height:70px;font-size:15px}\n.step{border:1px solid var(--line);border-radius:10px;padding:14px;margin-bottom:12px;background:#fcfcfd}\n.step .head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}\n.variant{border-left:3px solid var(--brand);padding-left:12px;margin:10px 0}\n.preview{white-space:pre-wrap;background:#fafbfc;border:1px solid var(--line);border-radius:8px;padding:12px;font-size:13px}\n.split{display:grid;grid-template-columns:380px 1fr;gap:16px}.list a.item{display:block;padding:10px 12px;border-bottom:1px solid var(--line);color:inherit}\n.list a.item:hover,.list a.item.on{background:#f3f5ff;text-decoration:none}.list a.unread{font-weight:600}\n.bubble{border:1px solid var(--line);border-radius:10px;padding:12px;margin-bottom:10px;white-space:pre-wrap}.bubble.in{background:#f3f5ff}\n.tabs a{margin-right:6px}.spark{display:flex;align-items:flex-end;gap:4px;height:70px}.spark div{flex:1;background:#c9d3ff;border-radius:3px 3px 0 0;position:relative}\n.spark div i{position:absolute;bottom:0;left:0;right:0;background:var(--ok);border-radius:3px 3px 0 0}\n.hide{display:none}\n@media(max-width:900px){aside{display:none}.g4,.g3,.g2,.split{grid-template-columns:1fr}main{padding:18px}}\n'}
